using System.Diagnostics;
using System.Reflection;
using FlaUI.Core.AutomationElements;
using FlaUI.UIA3;
using TomasAI.IFM.Domain.Reference.Shared.ServiceApi;
using TomasAI.IFM.UI.Net.Contracts;
using TomasAI.IFM.UI.Net.Views.Reference;
using TomasAI.IFM.UI.Rust.Bridge.Net;
using NativeApp=FlaUI.Core.Application;
public sealed class LiveStrategyCatalogParityTests
{
 [Fact]public void Live_both_catalog_views_show_the_same_exact_families_and_definition_without_mutation()
 {
  var baseline=Task.Run(async()=>{await using var s=new StrategyCatalogSession();return await s.ExecuteAsync(new(1,Guid.NewGuid(),"strategy-catalog","load",0,null,[]));}).GetAwaiter().GetResult();Assert.Equal(3,baseline.Rows.Length);
  using var host=new DesktopViewTestHost(scope=>{var form=new System.Windows.Forms.Form{Width=1500,Height=950,Text="WinForms strategy catalog parity"};var view=new StrategyCatalogReferenceView(scope.Container.GetInstance<IReferenceQueryApi>(),scope.Container.GetInstance<IReferenceCommandApi>()){Dock=System.Windows.Forms.DockStyle.Fill};form.Controls.Add(view);form.Shown+=(_,_)=>((IControlCommand)view).Load(scope,_=>{});return(form,()=>{view.Unload();return Task.CompletedTask;});});
  using var wf=new UIA3Automation();var window=wf.FromHandle(host.Handle).AsWindow();var list=Wait(window,e=>e.Properties.Name.ValueOrDefault=="Catalog definitions"&&e.AsListBox().Items.Length>=3,"loaded WinForms catalog").AsListBox();foreach(var row in baseline.Rows)Assert.Contains(list.Items,x=>x.Properties.Name.ValueOrDefault!.StartsWith(row.Fields["name"]));WaitName(window,"Strategy catalog definition details");WaitName(window,"Catalog code");WaitName(window,"Catalog name");var dir=Environment.GetEnvironmentVariable("IFM_RUST_TEST_ARTIFACTS")!;window.Capture().Save(Path.Combine(dir,"live-strategy-catalog-winforms.png"));
  var old=Environment.GetEnvironmentVariable("IFM_RUST_UI_MODE");Environment.SetEnvironmentVariable("IFM_RUST_UI_MODE","live");try{using var app=NativeApp.Launch(Environment.GetEnvironmentVariable("IFM_RUST_UI_EXE")!);using var automation=new UIA3Automation();try{Window? native=null;var watch=Stopwatch.StartNew();while(native is null&&watch.Elapsed<TimeSpan.FromSeconds(20)){var handle=NativeWindows.Find(app.ProcessId);if(handle!=IntPtr.Zero)native=automation.FromHandle(handle).AsWindow();Thread.Sleep(50);}Assert.NotNull(native);WaitName(native,"Strategy Catalog").AsButton().Invoke();Wait(native,e=>e.Properties.Name.ValueOrDefault=="Refresh catalog"&&e.IsEnabled,"enabled catalog refresh").AsButton().Invoke();foreach(var row in baseline.Rows)WaitName(native,$"{row.Fields["name"]} - v{row.Fields["version"]} ({row.Fields["status"]})");var first=baseline.Rows[0];WaitName(native,$"{first.Fields["name"]} - v{first.Fields["version"]} ({first.Fields["status"]})").AsButton().Invoke();WaitName(native,"Definition");Wait(native,e=>e.ControlType==FlaUI.Core.Definitions.ControlType.Edit&&e.Properties.Name.ValueOrDefault=="Name","labelled catalog name");Wait(native,e=>e.Properties.Name.ValueOrDefault=="Change definition"&&e.IsEnabled,"enabled catalog change").AsButton().Invoke();var nameEdit=Wait(native,e=>e.ControlType==FlaUI.Core.Definitions.ControlType.Edit&&e.Properties.Name.ValueOrDefault=="Name"&&e.IsEnabled,"editable catalog name").AsTextBox();nameEdit.Enter("Discarded parity edit");Wait(native,e=>e.Properties.Name.ValueOrDefault=="Discard catalog draft"&&e.IsEnabled,"enabled discard").AsButton().Invoke();Wait(native,e=>e.ControlType==FlaUI.Core.Definitions.ControlType.Edit&&e.Properties.Name.ValueOrDefault=="Name"&&!e.IsEnabled&&e.AsTextBox().Text==first.Fields["name"],"restored catalog name");native.Capture().Save(Path.Combine(dir,"live-strategy-catalog-rust.png"));}finally{if(!app.HasExited)app.Kill();}}finally{Environment.SetEnvironmentVariable("IFM_RUST_UI_MODE",old);}
 }
 static AutomationElement WaitName(Window w,string name)=>Wait(w,e=>e.Properties.Name.ValueOrDefault==name,name);
 static AutomationElement Wait(Window w,Func<AutomationElement,bool> predicate,string description){var watch=Stopwatch.StartNew();while(watch.Elapsed<TimeSpan.FromSeconds(25)){var found=w.FindAllDescendants().FirstOrDefault(predicate);if(found is not null)return found;Thread.Sleep(50);}var dir=Environment.GetEnvironmentVariable("IFM_RUST_TEST_ARTIFACTS")!;File.WriteAllLines(Path.Combine(dir,"catalog-failure-tree.txt"),w.FindAllDescendants().Select(e=>$"{e.ControlType}: {e.Properties.Name.ValueOrDefault}"));w.Capture().Save(Path.Combine(dir,"catalog-failure.png"));throw new TimeoutException("Missing catalog control: "+description);}
}
